using System.IO;
using System.Text.Json;
namespace DanceStudio;
public static class UiFeatureTests {
 public static void Run(string project,string output){Directory.CreateDirectory(output);var p=SongProject.Load(project);var rig=Rig.Load(p.Skeleton);var d=MotionClip.Load(p.Dance.Path,p.Dance.HkxBindingIndex,p.Dance.IdentityRigProof);var c=MotionClip.Load(p.Camera.Path,p.Camera.HkxBindingIndex,p.Camera.IdentityRigProof);var a=WaveAudio.Load(p.Audio.Path);p.CameraBone=97;p.ExportIn=30;p.ExportOut=31.5;int checks=0;string layout=Path.Combine(output,"mo2-fixture"),main=Path.Combine(layout,"LDA-main"),editor=Path.Combine(layout,"Editor","Tools","DanceStudio");Directory.CreateDirectory(Path.Combine(main,"SKSE","Plugins"));Directory.CreateDirectory(editor);File.WriteAllBytes(Path.Combine(main,"DanceStudioData.esl"),[]);File.WriteAllBytes(Path.Combine(main,"SKSE","Plugins","DanceStudio.dll"),[]);if(!ModLocation.IsModRoot(main))throw new Exception("empty song library discovery");checks++;if(ModLocation.Discover(editor,Path.Combine(layout,"no-cache"))!=Path.GetFullPath(main))throw new Exception("MO2 sibling discovery");checks++;foreach(double height in new[]{-25.0,0,25}){p.CameraHeightOffset=height;string saved=Path.Combine(output,"height"+height+".danceproj");p.Save(saved);if(SongProject.Load(saved).CameraHeightOffset!=height)throw new Exception("height save/load");checks++;string folder=Exporter.Export(output,p,d,c,a,rig);using var json=JsonDocument.Parse(File.ReadAllText(Path.Combine(folder,"tracks/camera.samples.json")));if(json.RootElement.GetProperty("heightOffset").GetDouble()!=height)throw new Exception("height game metadata");checks++;}File.WriteAllText(Path.Combine(output,"validation.json"),JsonSerializer.Serialize(new{passed=true,checks,gameTested=false},SongProject.Json));}
}
